/// 编辑焦点在格内还是编辑栏。缓冲只有一个（`self.editing`），位置只决定谁拿焦点。
#[derive(Default, Clone, Copy, PartialEq, Eq, Debug)]
enum EditSpot {
    /// 格内编辑框（键入 / F2 / 双击进入）
    #[default]
    Grid,
    /// 编辑栏输入行（点编辑栏或 fx 进入）
    FormulaBar,
}

#[derive(Default, Clone)]
struct EditState {
    buf: String,
    spot: EditSpot,
    /// 自动补全当前高亮项；缓冲区/候选变化时会被夹到范围内。
    complete_idx: usize,
    /// 最近一次处理 Alt+Enter 的帧，防止同一帧重复插入换行
    alt_frame: u64,
    /// 光标位置（字符下标）：点选单元格建立引用时按它插入/替换
    caret: usize,
    /// 下一步要把 TextEdit 的光标强制搬到这个字符位置（补全/点选引用后）
    caret_override: Option<usize>,
}

impl EditState {
    fn new(buf: String) -> Self {
        let caret = buf.chars().count();
        Self {
            buf,
            spot: EditSpot::Grid,
            complete_idx: 0,
            alt_frame: u64::MAX,
            caret,
            caret_override: None,
        }
    }
}

