/// 参数名来自函数签名：`SUM(number1,[number2],…)` → ["number1","number2（可选）"]。
fn fn_arg_names(name: &str) -> Vec<String> {
    let sig = formula_signature(name);
    let (Some(open), Some(close)) = (sig.find('('), sig.rfind(')')) else {
        return Vec::new();
    };
    let inner = &sig[open + 1..close];
    if inner.trim().is_empty() || inner.trim() == "参数…" {
        return Vec::new();
    }
    inner
        .split(',')
        .map(|p| p.trim().to_string())
        .filter(|p| !p.is_empty() && p != "…")
        .map(|p| {
            let opt = p.starts_with('[');
            let p = p.trim_matches(|c| c == '[' || c == ']');
            if opt {
                format!("{p}（可选）")
            } else {
                p.to_string()
            }
        })
        .collect()
}

/// 参数名去掉「（可选）」标记，用作输入框的值占位。
fn fn_arg_plain(label: &str) -> &str {
    label.trim_end_matches("（可选）")
}

/// 用向导里的参数拼出公式；一个参数都没填时给出 `=SUM()`（光标停在括号里）。
fn fn_formula_from_args(name: &str, args: &[String]) -> String {
    let used = args
        .iter()
        .rposition(|a| !a.trim().is_empty())
        .map(|i| i + 1)
        .unwrap_or(0);
    let inner = args[..used]
        .iter()
        .map(|a| a.trim().to_string())
        .collect::<Vec<_>>()
        .join(",");
    format!("={name}({inner})")
}

/// 公式自动补全/参数提示。`start` 是当前标识符在缓冲里的字节位置。
#[derive(Clone, Default)]
struct FormulaHelp {
    start: usize,
    token: String,
    suggestions: Vec<(String, String)>,
    signature: Option<String>,
}

impl FormulaHelp {
    fn selected(&self, idx: usize) -> Option<&str> {
        self.suggestions.get(idx.min(self.suggestions.len().saturating_sub(1))).map(|x| x.0.as_str())
    }
}

fn formula_signature(name: &str) -> String {
    let n = name.to_ascii_uppercase();
    let sig = match n.as_str() {
        "SUM" => "SUM(number1,[number2],…)",
        "SUMIF" => "SUMIF(range,criteria,[sum_range])",
        "SUMIFS" => "SUMIFS(sum_range,criteria_range1,criteria1,…)",
        "AVERAGE" => "AVERAGE(number1,[number2],…)",
        "COUNT" => "COUNT(value1,[value2],…)",
        "COUNTA" => "COUNTA(value1,[value2],…)",
        "IF" => "IF(logical_test,[value_if_true],[value_if_false])",
        "IFS" => "IFS(test1,value1,[test2,value2],…)",
        "VLOOKUP" => "VLOOKUP(lookup_value,table_array,col_index_num,[range_lookup])",
        "XLOOKUP" => "XLOOKUP(lookup_value,lookup_array,return_array,[if_not_found],[match_mode],[search_mode])",
        "INDEX" => "INDEX(array,row_num,[column_num])",
        "MATCH" => "MATCH(lookup_value,lookup_array,[match_type])",
        "TEXT" => "TEXT(value,format_text)",
        "ROUND" => "ROUND(number,num_digits)",
        "DATE" => "DATE(year,month,day)",
        "FILTER" => "FILTER(array,include,[if_empty])",
        "UNIQUE" => "UNIQUE(array,[by_col],[exactly_once])",
        "SORT" => "SORT(array,[sort_index],[sort_order],[by_col])",
        "LET" => "LET(name1,value1,[name2,value2],…,calculation)",
        _ => return format!("{n}(参数…)"),
    };
    sig.to_string()
}

fn function_desc(name: &str) -> &'static str {
    match name {
        "SUM" => "求和",
        "SUMIF" => "条件求和",
        "SUMIFS" => "多条件求和",
        "AVERAGE" => "平均值",
        "COUNT" => "数字计数",
        "COUNTA" => "非空计数",
        "IF" => "条件判断",
        "IFS" => "多条件判断",
        "VLOOKUP" => "纵向查找",
        "XLOOKUP" => "查找",
        "INDEX" => "索引取值",
        "MATCH" => "定位",
        "TEXT" => "格式化文本",
        "ROUND" => "四舍五入",
        "DATE" => "日期",
        "FILTER" => "筛选",
        "UNIQUE" => "去重",
        "SORT" => "排序",
        "LET" => "定义局部名称",
        "NOW" => "当前时间",
        "TODAY" => "今天",
        "MAX" => "最大值",
        "MIN" => "最小值",
        _ => "函数",
    }
}

/// 取 `=` 后正在输入的函数名前缀；不是公式、没有标识符或前缀是数字时返回 None。
fn formula_token_start(buf: &str) -> Option<usize> {
    if !buf.starts_with('=') {
        return None;
    }
    let mut start = buf.len();
    for (i, ch) in buf.char_indices().rev() {
        if ch.is_ascii_alphanumeric() || ch == '.' || ch == '_' {
            start = i;
        } else {
            break;
        }
    }
    if start == buf.len() {
        return None;
    }
    let token = &buf[start..];
    if token.chars().next()?.is_ascii_digit() {
        return None;
    }
    let prev = buf[..start].chars().last();
    let ok = matches!(
        prev,
        None | Some('=') | Some('(') | Some(',') | Some('+') | Some('-') | Some('*')
            | Some('/') | Some('^') | Some('&') | Some('<') | Some('>') | Some(':')
            | Some(';') | Some('{')
    );
    if !ok {
        return None;
    }
    Some(start)
}

/// 当前最内层未闭合函数的签名（只对已实现函数显示）。
fn formula_open_signature(buf: &str) -> Option<String> {
    if !buf.starts_with('=') {
        return None;
    }
    let mut depth = 0i32;
    let mut open = None;
    for (i, ch) in buf.char_indices().rev() {
        match ch {
            ')' => depth += 1,
            '(' => {
                if depth == 0 {
                    open = Some(i);
                    break;
                }
                depth -= 1;
            }
            _ => {}
        }
    }
    let open = open?;
    let mut start = open;
    while start > 0 {
        let ch = buf[..start].chars().next_back()?;
        if ch.is_ascii_alphanumeric() || ch == '.' || ch == '_' {
            start -= ch.len_utf8();
        } else {
            break;
        }
    }
    if start == open {
        return None;
    }
    let name = buf[start..open].to_ascii_uppercase();
    if sheetcore::formula::functions::implemented().iter().any(|f| *f == name) {
        Some(formula_signature(&name))
    } else {
        None
    }
}

fn formula_help(buf: &str) -> Option<FormulaHelp> {
    let mut out = FormulaHelp::default();
    if let Some(start) = formula_token_start(buf) {
        let token = &buf[start..];
        if token.chars().count() >= 2 {
            let up = token.to_ascii_uppercase();
            for f in sheetcore::formula::functions::implemented() {
                if f.starts_with(&up) {
                    out.suggestions.push((f.to_string(), function_desc(f).to_string()));
                }
            }
            out.suggestions.sort_by(|a, b| a.0.len().cmp(&b.0.len()).then(a.0.cmp(&b.0)));
            out.suggestions.truncate(8);
            out.start = start;
            out.token = token.to_string();
        }
    }
    out.signature = formula_open_signature(buf);
    if out.suggestions.is_empty() && out.signature.is_none() {
        None
    } else {
        Some(out)
    }
}

/// 候选列表的键盘选择：↑↓ 改变高亮，Enter/Tab 接受；返回要接受的索引。
fn formula_help_keys(
    ctx: &egui::Context,
    help: &FormulaHelp,
    selected: &mut usize,
) -> Option<usize> {
    if help.suggestions.is_empty() {
        return None;
    }
    *selected = (*selected).min(help.suggestions.len().saturating_sub(1));
    let up = ctx.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::ArrowUp));
    let down = ctx.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::ArrowDown));
    if up {
        *selected = if *selected == 0 {
            help.suggestions.len() - 1
        } else {
            *selected - 1
        };
    }
    if down {
        *selected = (*selected + 1) % help.suggestions.len();
    }
    let accept = ctx.input_mut(|i| {
        i.consume_key(egui::Modifiers::NONE, egui::Key::Tab)
            || i.consume_key(egui::Modifiers::NONE, egui::Key::Enter)
    });
    accept.then_some(*selected)
}

fn apply_formula_pick(ed: &mut EditState, help: &FormulaHelp, idx: usize) {
    let Some(name) = help.selected(idx).map(str::to_string) else {
        return;
    };
    if ed.buf.len() < help.start {
        return;
    }
    if std::env::var("SC_FORMULA_LOG").is_ok() {
        eprintln!(
            "[formula] pick idx={} start={} token={:?} name={:?} before={:?}",
            idx, help.start, help.token, name, ed.buf
        );
    }
    ed.buf.replace_range(help.start.., &name);
    // Excel 选中函数后补左括号，紧接着显示参数签名
    if !ed.buf.ends_with('(') {
        ed.buf.push('(');
    }
    ed.complete_idx = 0;
}

/// UI-11.3：A1 引用判定（列 1-3 个字母、行 1-7 位数字，$ 可选，行号不能是 0）。
fn is_a1_ref(s: &str) -> bool {
    let b: Vec<char> = s.chars().collect();
    if b.is_empty() {
        return false;
    }
    let mut i = 0;
    if b[i] == '$' {
        i += 1;
    }
    let cs = i;
    while i < b.len() && b[i].is_ascii_alphabetic() {
        i += 1;
    }
    let letters = i - cs;
    if !(1..=3).contains(&letters) {
        return false;
    }
    if i < b.len() && b[i] == '$' {
        i += 1;
    }
    let ds = i;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
    }
    i > ds && i == b.len() && b[ds] != '0'
}

/// 引用或 `A1:B2` 范围，可带 `Sheet!` / `'My Sheet'!` 前缀。
fn looks_like_ref(tok: &str) -> bool {
    let tail = match tok.rfind('!') {
        Some(i) => &tok[i + 1..],
        None => tok,
    };
    let parts: Vec<&str> = tail.split(':').collect();
    !parts.is_empty() && parts.len() <= 2 && parts.iter().all(|p| is_a1_ref(p))
}

/// 从 `pos` 起解析一个 A1 引用（含可选 `$`），返回结束的字符下标。
fn a1_end(chars: &[char], pos: usize) -> Option<usize> {
    let mut i = pos;
    if i < chars.len() && chars[i] == '$' {
        i += 1;
    }
    let cs = i;
    while i < chars.len() && chars[i].is_ascii_alphabetic() {
        i += 1;
    }
    if !(1..=3).contains(&(i - cs)) {
        return None;
    }
    if i < chars.len() && chars[i] == '$' {
        i += 1;
    }
    let ds = i;
    while i < chars.len() && chars[i].is_ascii_digit() {
        i += 1;
    }
    if i == ds || chars[ds] == '0' {
        return None;
    }
    Some(i)
}

/// 从 `i` 起解析「[可选表名!]引用[:引用]」，返回结束下标与原文。
fn parse_ref_token(chars: &[char], i: usize) -> Option<(usize, String)> {
    let mut j = i;
    if i < chars.len() && chars[i] == '\'' {
        let mut k = i + 1;
        while k < chars.len() && chars[k] != '\'' {
            k += 1;
        }
        if k >= chars.len() {
            return None;
        }
        j = k + 1;
        if j >= chars.len() || chars[j] != '!' {
            return None;
        }
    } else {
        let mut k = j;
        while k < chars.len()
            && (chars[k].is_alphanumeric() || matches!(chars[k], '_' | '.'))
        {
            k += 1;
        }
        if k > i && k < chars.len() && chars[k] == '!' {
            j = k;
        }
    }
    if j != i {
        if j >= chars.len() || chars[j] != '!' {
            return None;
        }
        j += 1;
    }
    let mut end = a1_end(chars, j)?;
    if end < chars.len() && chars[end] == ':' {
        if let Some(e2) = a1_end(chars, end + 1) {
            end = e2;
        }
    }
    Some((end, chars[i..end].iter().collect()))
}

/// UI-11.3：点选单元格建立引用 —— 光标左侧若是引用/正在输入的引用就整段替换，
/// 否则在光标处插入。返回新缓冲与新光标（字符下标）。Excel 同款行为。
/// 工作表名在引用里的写法：名字含空格、标点、以数字开头等要加单引号（Excel 规则）。
pub(crate) fn sheet_ref_name(name: &str) -> String {
    let plain = !name.is_empty()
        && !name.chars().next().is_some_and(|c| c.is_ascii_digit())
        && name
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_' || c == '.' || c > '\u{7f}');
    if plain {
        name.to_string()
    } else {
        format!("'{}'", name.replace('\'', "''"))
    }
}

pub(crate) fn insert_reference(buf: &str, caret: usize, label: &str) -> (String, usize) {
    let chars: Vec<char> = buf.chars().collect();
    let caret = caret.min(chars.len());
    let mut start = caret;
    while start > 0 {
        let ch = chars[start - 1];
        if ch.is_alphanumeric() || matches!(ch, '$' | '_' | '.' | '!' | ':' | '\'') {
            start -= 1;
        } else {
            break;
        }
    }
    let left: String = chars[start..caret].iter().collect();
    let start = if looks_like_ref(&left) { start } else { caret };
    let mut out: String = chars[..start].iter().collect();
    out.push_str(label);
    out.extend(chars[caret..].iter());
    (out, start + label.chars().count())
}

/// UI-11.5：把缓冲里的 [s,e) 换成 text，返回新缓冲与新光标。
pub(crate) fn replace_char_span(buf: &str, span: (usize, usize), text: &str) -> (String, usize) {
    let chars: Vec<char> = buf.chars().collect();
    let s = span.0.min(chars.len());
    let e = span.1.max(s).min(chars.len());
    let mut out: String = chars[..s].iter().collect();
    out.push_str(text);
    out.extend(chars[e..].iter());
    (out, s + text.chars().count())
}

/// UI-11.5：两格之间的区域引用，锚点在前（从 B3 拖回 A1 显示 B3:A1，和 Excel 一致）。
pub(crate) fn range_label(a: (u32, u32), b: (u32, u32)) -> String {
    format!("{}:{}", cell_name(a.0, a.1), cell_name(b.0, b.1))
}

/// UI-11.5：整列引用 `A:A`。
pub(crate) fn whole_col_label(c: u32) -> String {
    let l = col_label(c);
    format!("{l}:{l}")
}

/// UI-11.5：整行引用 `1:1`。
pub(crate) fn whole_row_label(r: u32) -> String {
    format!("{}:{}", r + 1, r + 1)
}

/// UI-11.3：公式里的引用片段（字符区间 + 调色序号），同一文本共用同色。
pub(crate) fn ref_spans(buf: &str) -> Vec<(usize, usize, usize)> {
    let chars: Vec<char> = buf.chars().collect();
    let mut out: Vec<(usize, usize, usize)> = Vec::new();
    let mut seen: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < chars.len() {
        let boundary = i == 0
            || !(chars[i - 1].is_alphanumeric()
                || matches!(chars[i - 1], '_' | '$' | '.' | '\''));
        if !boundary {
            i += 1;
            continue;
        }
        if let Some((end, text)) = parse_ref_token(&chars, i) {
            let right_ok = end == chars.len()
                || !(chars[end].is_alphanumeric() || matches!(chars[end], '_' | '$'));
            if right_ok {
                let ci = match seen.iter().position(|t| t == &text) {
                    Some(p) => p,
                    None => {
                        seen.push(text);
                        seen.len() - 1
                    }
                };
                out.push((i, end, ci));
                i = end;
                continue;
            }
        }
        i += 1;
    }
    out
}

/// 引用配色（Excel 习惯的多引用颜色循环）。
fn ref_color(idx: usize) -> egui::Color32 {
    const PALETTE: [egui::Color32; 4] = [
        egui::Color32::from_rgb(31, 111, 208),
        egui::Color32::from_rgb(26, 138, 59),
        egui::Color32::from_rgb(138, 63, 176),
        egui::Color32::from_rgb(161, 92, 0),
    ];
    PALETTE[idx % PALETTE.len()]
}

/// UI-11.3：编辑框的着色版排版 —— 公式里的引用按出现顺序上色，其余部分正常色。
/// 非公式文本原样一段，避免影响普通输入。
pub(crate) fn formula_layout_job(
    text: &str,
    font: egui::FontId,
    normal: egui::Color32,
) -> egui::text::LayoutJob {
    let mut job = egui::text::LayoutJob::default();
    if !text.starts_with('=') {
        job.append(
            text,
            0.0,
            egui::TextFormat { font_id: font, color: normal, ..Default::default() },
        );
        return job;
    }
    let byte_of: Vec<usize> = text
        .char_indices()
        .map(|(b, _)| b)
        .chain(std::iter::once(text.len()))
        .collect();
    let mut last = 0usize;
    for (s, e, ci) in ref_spans(text) {
        if s < last || e > byte_of.len() {
            continue;
        }
        let (bs, be) = (byte_of[s], byte_of[e]);
        if bs > last {
            job.append(
                &text[last..bs],
                0.0,
                egui::TextFormat { font_id: font.clone(), color: normal, ..Default::default() },
            );
        }
        job.append(
            &text[bs..be],
            0.0,
            egui::TextFormat { font_id: font.clone(), color: ref_color(ci), ..Default::default() },
        );
        last = be;
    }
    if last < text.len() {
        job.append(
            &text[last..],
            0.0,
            egui::TextFormat { font_id: font, color: normal, ..Default::default() },
        );
    }
    if std::env::var("SC_FORMULA_LOG").is_ok() {
        let cs: Vec<String> = job
            .sections
            .iter()
            .map(|s| format!("{:?}={:?}", s.byte_range, s.format.color))
            .collect();
        eprintln!("[lay] text={text:?} secs={cs:?}");
    }
    job
}

/// 在编辑框下方（放不下则上方）画候选/签名提示。
fn draw_formula_help(
    ctx: &egui::Context,
    anchor: egui::Pos2,
    above: bool,
    help: &FormulaHelp,
    selected: usize,
) {
    let screen = ctx.screen_rect();
    let h = 22.0 * help.suggestions.len().min(8) as f32
        + if help.suggestions.is_empty() { 0.0 } else { 6.0 }
        + if help.signature.is_some() { 22.0 } else { 0.0 }
        + 8.0;
    let y = if above {
        (anchor.y - h - 2.0).max(screen.top() + 4.0)
    } else {
        anchor.y.min(screen.bottom() - h - 4.0)
    };
    egui::Area::new(egui::Id::new("formula_complete"))
        .fixed_pos(egui::pos2(anchor.x, y))
        .order(egui::Order::Foreground)
        .show(ctx, |ui| {
            egui::Frame::popup(ui.style()).show(ui, |ui| {
                ui.set_min_width(250.0);
                ui.spacing_mut().item_spacing.y = 1.0;
                for (i, (name, desc)) in help.suggestions.iter().enumerate() {
                    let mut rich = egui::RichText::new(format!("{name}    {desc}")).size(11.5);
                    if i == selected {
                        rich = rich.background_color(egui::Color32::from_rgb(212, 228, 246));
                    }
                    ui.label(rich);
                }
                if let Some(sig) = &help.signature {
                    if !help.suggestions.is_empty() {
                        ui.separator();
                    }
                    ui.label(
                        egui::RichText::new(sig)
                            .size(11.0)
                            .color(egui::Color32::from_rgb(90, 90, 90)),
                    );
                }
            });
        });
}


/// F4 循环当前末尾的 A1 引用：A1 → $A$1 → A$1 → $A1 → A1。
fn cycle_formula_ref(buf: &mut String) -> bool {
    let bytes = buf.as_bytes();
    let mut end = bytes.len();
    while end > 0 && !(bytes[end - 1].is_ascii_alphanumeric() || bytes[end - 1] == b'$') {
        end -= 1;
    }
    if end == 0 {
        return false;
    }
    let mut start = end;
    while start > 0 && (bytes[start - 1].is_ascii_alphanumeric() || bytes[start - 1] == b'$') {
        start -= 1;
    }
    // 排除函数名/数字，只接受 [A-Za-z$]{1,3}[0-9]+ 且前后不是标识符
    let token = &buf[start..end];
    let tchars: Vec<char> = token.chars().collect();
    let mut tpos = 0usize;
    let mut letters = String::new();
    while tpos < tchars.len() && (tchars[tpos] == '$' || tchars[tpos].is_ascii_alphabetic()) {
        if tchars[tpos] != '$' {
            letters.push(tchars[tpos].to_ascii_uppercase());
        }
        tpos += 1;
    }
    let rest: String = tchars[tpos..].iter().collect();
    if letters.is_empty() || letters.len() > 3 || rest.is_empty() || !rest.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    if start > 0 {
        let prev = buf[..start].chars().next_back().unwrap_or(' ');
        if prev.is_ascii_alphanumeric() || prev == '_' || prev == '.' {
            return false;
        }
    }
    if end < buf.len() {
        let next = buf[end..].chars().next().unwrap_or(' ');
        if next.is_ascii_alphanumeric() || next == '_' {
            return false;
        }
    }
    // 解析当前 $ 状态；A1→$A$1→A$1→$A1→A1
    let chars: Vec<char> = token.chars().collect();
    let mut ci = 0;
    let col_abs = chars.get(ci) == Some(&'$');
    if col_abs {
        ci += 1;
    }
    let col_start = ci;
    while ci < chars.len() && chars[ci].is_ascii_alphabetic() {
        ci += 1;
    }
    let col = chars[col_start..ci].iter().collect::<String>();
    let row_abs = chars.get(ci) == Some(&'$');
    if row_abs {
        ci += 1;
    }
    let row = chars[ci..].iter().collect::<String>();
    let next = match (col_abs, row_abs) {
        (false, false) => (true, true),
        (true, true) => (false, true),
        (false, true) => (true, false),
        (true, false) => (false, false),
    };
    let mut out = String::new();
    if next.0 {
        out.push('$');
    }
    out.push_str(&col);
    if next.1 {
        out.push('$');
    }
    out.push_str(&row);
    buf.replace_range(start..end, &out);
    true
}


/// 数据验证的警告/信息提示框（Excel 的「是/否/取消」与「确定」）。
